mapper.select:
select * from ( select c.chat_conversation_id as chatConversationId, c.update_time as updateTime, c.good_id as goodId, case when c.user_id = #{userId} then u2.user_id else c.user_id end as userId, -- 发送方ID case when c.user_id = #{userId} then u2.user_name else u1.user_name end as userName, -- 发送方用户名 case when c.user_id = #{userId} then u2.avatar else u1.avatar end as avatar, -- 发送方头像 case when c.user_id = #{userId} then c.focused_user_id else u2.user_id end as byUserId, -- 接收方ID case when c.user_id = #{userId} then u1.user_name else u2.user_name end as byUserName, -- 接收方用户名 case when c.user_id = #{userId} then u1.avatar else u2.avatar end as byAvatar, -- 接收方头像 (select content from chat_content cc where cc.chat_conversation_id=c.chat_conversation_id order by cc.create_time desc limit 1) as content, (select create_time from chat_content cc where cc.chat_conversation_id=c.chat_conversation_id order by cc.create_time desc limit 1) as messageTime, (select message_type from chat_content cc where cc.chat_conversation_id=c.chat_conversation_id order by cc.create_time desc limit 1) as messageType, (select count(*) from chat_content cc where cc.chat_conversation_id=c.chat_conversation_id and user_id != #{userId} and status=0) as contentCount from chat_conversation c left join tb_user u1 on u1.user_id = c.user_id left join tb_user u2 on u2.user_id = c.focused_user_id where u1.user_id is not null and u2.user_id is not null
and (c.user_id = #{userId} or c.focused_user_id = #{userId})
and u2.user_id = #{focusedUserId}
and (u1.user_name like CONCAT('%',#{nickName},'%') or u2.user_name like CONCAT('%',#{nickName},'%'))
and c.chat_conversation_id in (select chat_conversation_id from chat_content where content like concat('%',#{content},'%'))
and c.is_delete is null
and (u1.phone like CONCAT('%',#{phone},'%') or u2.phone like CONCAT('%',#{phone},'%'))
and c.create_time >= #{startTime}
and c.create_time <= #{endTime}
) a order by messageTime desc
